C maior)?","category":"harmonia","options":["D","E","F","G","Não sei"],"correct":1},{"id":"voc_tom","type":"quiz","text":"Se uma música força notas agudas e gera tensão, a primeira ação é:","category":"tecnica_especifica","options":["Cantar mais forte","Pedir avaliação do tom e ajustar","Prender a respiração","Evitar aquecimento","Não sei"],"correct":1}]}},{"id":"pessoal","kicker":"Plano de desenvolvimento","title":"Próximos passos","questions":[{"id":"repertorio","type":"text","text":"Qual música do repertório melhor representa sua execução atual?","required":true,"placeholder":"Nome da música"},{"id":"dificuldade","type":"textarea","text":"Em qual situação concreta você sente mais dificuldade?","required":true,"placeholder":"Ex.: manter a segunda voz no refrão, voltar da virada no tempo..."},{"id":"meta_90","type":"textarea","text":"O que você gostaria de conseguir fazer com segurança nos próximos 90 dias?","required":true,"placeholder":"Defina uma meta observável"},{"id":"estudo","type":"single","text":"Quanto tempo real você consegue reservar para estudar por semana?","required":true,"options":["Até 30 min","30–60 min","1–2 horas","2–4 horas","Mais de 4 horas"]},{"id":"observacao","type":"textarea","text":"Há algo que o avaliador precisa saber?","required":false,"placeholder":"Opcional"}]}]$bank$::jsonb;
  v_revision uuid := gen_random_uuid();
  v_updated_at timestamptz := now();
begin
  insert into private.question_bank_versions (revision, data, published_at, published_by)
  values (v_revision, v_data, v_updated_at, null)
  on conflict (revision) do update set data = excluded.data, published_at = excluded.published_at, published_by = null;
  insert into private.question_banks (id, data, revision, updated_at, updated_by)
  values (1, v_data, v_revision, v_updated_at, null)
  on conflict (id) do update set data = excluded.data, revision = excluded.revision, updated_at = excluded.updated_at, updated_by = null;
  insert into public.question_banks (id, data, revision, updated_at, updated_by)
  values (1, private.sanitize_question_bank(v_data), v_revision, v_updated_at, null)
  on conflict (id) do update set data = excluded.data, revision = excluded.revision, updated_at = excluded.updated_at, updated_by = null;
end;
$seed$;
